//! The WGSL shaders, which are the reference implementation of every edit
//! operation, and the wgpu pipeline that runs them for export and edited
//! thumbnails (technical design, section 6; decision 0004).
//!
//! The same shader source runs in the preview: the UI gets it, and the GLSL
//! ES translation for WebGL2, from files generated by this crate's tests
//! (`ui/src/preview/generated/`).

pub mod check;
mod export;
mod renderer;
mod settings;

pub use export::{ExportError, export_jpeg};
pub use renderer::{Output, RenderError, Renderer};
pub use settings::Settings;

/// The shader source: shared color functions, then each stage's
/// operations, then the luminance guide, then the render pass. WGSL has no includes, so the files
/// are joined in this order, here and in the generated files.
pub const SHADER: &str = concat!(
    include_str!("../shaders/color.wgsl"),
    "\n",
    include_str!("../shaders/tone.wgsl"),
    "\n",
    include_str!("../shaders/guide.wgsl"),
    "\n",
    include_str!("../shaders/main.wgsl"),
);
